pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Restrict array lengths to a manageable range and ensure they match
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        vm.assume(_tos.length <= 5);

        // Use an adversarial callee that does not revert on low-level call failure
        // to exercise the unchecked return value path.
        NoCodeCallee callee = new NoCodeCallee();

        bool success;
        try c.transfer(from, address(callee), _tos, v) returns (bool ret) {
            // If we get here, the call didn't revert.
            // The rule: return value must be true ALWAYS when the transaction doesn't revert.
            assertTrue(ret);
        } catch {
            // If it reverts, the return value is irrelevant for this property.
            // We just let it pass.
        }
    }
}

// Helper: a contract with no code that causes low-level call to return false
// without reverting the entire transaction, because the caller doesn't check the return value.
contract NoCodeCallee { }

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Restrict to admissible domain: arrays must have same length and be non-empty
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Restrict addresses to avoid precompiles/storage that could affect call success beyond our model
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        // Avoid system addresses
        vm.assume(uint160(caddress) > 100);

        // Execute transfer and capture success/revert
        (bool success, bytes memory returnData) =
            address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));

        if (success) {
            // Decode the return value only if call did not revert
            bool returned = abi.decode(returnData, (bool));
            // Rule: if the call succeeds, the return value must be true
            assertTrue(returned);
        }
        // If the call reverts, we make no assertion about the return value
    }
}

